import{_ as e,o,c as s,al as a}from"./chunks/framework.Bm7de0lE.js";const u=JSON.parse('{"title":"表单参与与重置","description":"","frontmatter":{},"headers":[],"relativePath":"guide/forms.md","filePath":"guide/forms.md","lastUpdated":1786483032000}'),d={name:"guide/forms.md"};function i(c,t,n,l,p,r){return o(),s("div",null,[...t[0]||(t[0]=[a(`<h1 id="表单参与与重置" tabindex="-1">表单参与与重置 <a class="header-anchor" href="#表单参与与重置" aria-label="Permalink to &quot;表单参与与重置&quot;">​</a></h1><p>复合控件的值攥在自己的机器里，浏览器看不见。要让它随 <code>&lt;form&gt;</code> 一起提交、一起重置，靠两件事： 一份<strong>表单影子</strong>（把值映射成原生输入）和一条<strong>重置事件</strong>（把宿主表单的 <code>reset</code> 翻译进机器）。</p><h2 id="表单影子" tabindex="-1">表单影子 <a class="header-anchor" href="#表单影子" aria-label="Permalink to &quot;表单影子&quot;">​</a></h2><p>给了 <code>name</code> 才生出影子，不给就整条不参与提交——既有 DOM 一个字节不变。</p><div class="language-vue vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">XhSwitch</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;notify&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> default-checked</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><p>提交出去是 <code>notify=on</code>。值可以换：<code>&lt;XhSwitch name=&quot;theme&quot; value=&quot;dark&quot; /&gt;</code> 提交 <code>theme=dark</code>。</p><p>三种形态，按组件的值形状分：</p><table tabindex="0"><thead><tr><th>形态</th><th>谁在用</th><th>说明</th></tr></thead><tbody><tr><td>单个 <code>hidden-input</code></td><td>color-picker、combobox、tree-select、checkbox、switch、rating……</td><td>多值的按逗号拼成一串</td></tr><tr><td>一值一个影子输入</td><td>checkbox-group、radio-group</td><td>与原生 checkbox / radio 同构，靠 <code>checked</code> 表达选中</td></tr><tr><td>隐藏 <code>&lt;select&gt;</code></td><td>select</td><td>多选直接开原生 <code>multiple</code></td></tr></tbody></table><p><strong>勾选类控件的语义与原生一致</strong>：没勾就整条不进 <code>FormData</code>，不是提交一个空值。checkbox 的半选 （<code>indeterminate</code>）按未勾处理——原生里它也只是外观，提交与否看 <code>checked</code>。</p><p>影子在两个适配器里的来路不同：</p><ul><li><strong>Vue</strong>：单体控件（checkbox、switch）由组件自己渲染，给了 <code>name</code> 才有那个节点；有子部件的组件 由作者写上对应部件，例如 <code>&lt;XhComboboxHiddenInput /&gt;</code>。</li><li><strong>Web Components</strong>：一律由作者写 <code>data-xh-part=&quot;hidden-input&quot;</code> 的原生节点，元素只负责往上铺属性。</li></ul><div class="tip custom-block"><p class="custom-block-title">为什么 <code>type=hidden</code> 能放进 <code>&lt;button&gt;</code></p><p>checkbox 与 switch 的根是 <code>&lt;button&gt;</code>，而 HTML 的内容模型禁止 button 有交互内容后代。 <code>&lt;input type=&quot;hidden&quot;&gt;</code> 不在其列——规范里 input 那条写的是「type 属性<strong>不处于 Hidden 状态时</strong>」， 所以这样嵌是合法的。</p></div><h2 id="表单重置" tabindex="-1">表单重置 <a class="header-anchor" href="#表单重置" aria-label="Permalink to &quot;表单重置&quot;">​</a></h2><p>带 <code>name</code> 的组件都认表单重置。点 <code>&lt;button type=&quot;reset&quot;&gt;</code>（或调 <code>form.reset()</code>），它们各自回到 自己的默认值，和旁边的原生输入框一起。</p><div class="language-vue vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">form</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;XhRadioGroupRoot name=&quot;plan&quot; default-value=&quot;standard&quot;&gt;…&lt;/XhRadioGroupRoot&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;XhRatingRoot name=&quot;score&quot; :default-value=&quot;3&quot;&gt;…&lt;/XhRatingRoot&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;button type=&quot;reset&quot;&gt;重置&lt;/button&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">form</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>几条要点：</p><p><strong>落点按当下的 props 重算</strong>，不是挂载那一刻冻结的值。宿主把 <code>defaultValue</code> 换掉（比如切去编辑 另一条记录），重置就回到新的那一份——与原生 <code>reset()</code> 回到「当下的 default」一致。</p><p><strong>受控组件只发意图。</strong> 组件不会自改状态，只调一次 <code>onValueChange</code>（或 <code>onCheckedChange</code>）， 由宿主写回。</p><div class="warning custom-block"><p class="custom-block-title">受控组件要拿到重置，必须显式传 <code>defaultValue</code></p><p>这是本库与「受控 reset 是纯空操作」的分歧点，也是最容易踩的一条。</p><p>组件内部那句 <code>?? 兜底</code> 把「宿主声明的默认值」和「组件的空值」写在同一个表达式里 （radio-group 是 <code>null</code>、rating 是 <code>0</code>、tags-input 是空数组）。受控且没写 <code>defaultValue</code> 时， 组件<strong>一动不动、一条意图都不发</strong>——否则那个空值会被当成默认值发给宿主，重置就成了「把你的数据抹掉」。</p></div><p><strong>重置被拦下就不动。</strong> 表单那侧 <code>event.preventDefault()</code> 之后，同表单的原生控件也没还原， 组件单方面还原会拼出半份默认值。</p><p><strong>归属在事件那一刻现算。</strong> 监听挂在组件所在的根节点上而不是那个 <code>&lt;form&gt;</code> 上（表单会被条件渲染 换掉、组件也会被搬走），用 <code>closest(&#39;form&#39;)</code> 比对，因此嵌套表单不会误伤。</p><p>不在任何表单里、无 DOM 的服务端、作者没写影子输入——三种情形都不需要特别处理：归属判定不命中、 服务端根本不挂副作用、锚点是组件根节点而不是影子输入。</p><h2 id="哪些组件参与" tabindex="-1">哪些组件参与 <a class="header-anchor" href="#哪些组件参与" aria-label="Permalink to &quot;哪些组件参与&quot;">​</a></h2><p>20 个：checkbox、checkbox-group、color-picker、combobox、date-field、date-picker、editable、 file-upload、number-field、pin-input、radio-group、rating、select、slider、switch、tags-input、 text-field、time-field、time-picker、tree-select。</p><p>新加的表单组件忘了接重置会被门禁拦下：判据的分母是从源码里扫出来的（<code>types</code> 的 props 里有 <code>name?: string</code> 即表单字段），不是手写名单。</p>`,25)])])}const g=e(d,[["render",i]]);export{u as __pageData,g as default};
